const organic = ($input.first().json.organic) || [];
const competitors = organic.slice(0, 8).map((r) => ({
  title: r.title || "",
  snippet: r.snippet || "",
  link: r.link || "",
}));
return [{ json: { competitors } }];

const formData = $input.all()[0].json;
return [{
