parameters.jsCode:
const d = $input.first().json;

if (!d.category_breakdown || !d.total_score) {
  return [{ json: { html: '<h2>Error: No analysis data received. Please try again.</h2>' } }];
}

const scoreColor = d.total_score >= 70 ? '#10b981' : d.total_score >= 40 ? '#f59e0b' : '#ef4444';
const confColor = d.confidence_label === 'HIGH CONFIDENCE' ? '#10b981' : '#f59e0b';
const confBg = d.confidence_label === 'HIGH CONFIDENCE' ? '#ecfdf5' : '#fffbeb';

const categoryCards = d.category_breakdown.map(c => {
  const ratio = c.score / c.max;
  const catColor = ratio >= 0.7 ? '#10b981' : ratio >= 0.4 ? '#f59e0b' : '#ef4444';
  const catBg = ratio >= 0.7 ? '#ecfdf5' : ratio >= 0.4 ? '#fffbeb' : '#fef2f2';
  return `<div style="margin-bottom:12px;padding:14px 18px;background:${catBg};border-radius:10px;border-left:4px solid ${catColor}">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
      <strong style="font-size:15px;color:#1f2937">${c.category}</strong>
      <span style="font-size:20px;font-weight:700;color:${catColor}">${c.score}/${c.max}</span>
    </div>
    <p style="margin:4px 0;color:#4b5563;font-size:13px;line-height:1.4">${c.justification || ''}</p>
    <p style="margin:4px 0;font-size:13px;color:#1f2937"><strong>Top Fix:</strong> ${c.top_fix || ''}</p>
    ${c.data_point ? `<p style="margin:4px 0;font-size:12px;color:#6b7280"><em>Based on:</em> ${c.data_point}</p>` : ''}
  </div>`;
}).join('\n');

const priorityItems = d.priority_actions.map(a => {
  const stageColors = { 'Impressions': '#dbeafe;#2563eb', 'Clicks': '#fef3c7;#d97706', 'Orders/Conversion': '#ecfdf5;#059669' };
  const [bg, tx] = (stageColors[a.funnel_stage] || '#f3f4f6;#374151').split(';');
  return `<li style="margin-bottom:10px;padding:12px 16px;background:#fff;border:1px solid #e5e7eb;border-radius:8px;display:flex;align-items:center;justify-content:space-between">
    <span style="font-size:14px;color:#1f2937;flex:1"><strong>${a.rank}.</strong> ${a.action}</span>
    <span style="margin-left:12px;padding:3px 12px;border-radius:99px;font-size:11px;font-weight:600;white-space:nowrap;background:${bg};color:${tx}">${a.funnel_stage}</span>
  </li>`;
}).join('\n');

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><style>
  body { font-family: system-ui, -apple-system, sans-serif; background:#f0f2f5; margin:0; padding:24px; }
  .card { max-width:680px; margin:0 auto; background:#fff; border-radius:16px; padding:32px; box-shadow:0 4px 24px rgba(0,0,0,0.08); }
  h1 { margin:0 0 2px; font-size:22px; color:#111; font-weight:700; }
  .score-row { display:flex; align-items:center; gap:14px; margin:12px 0 4px; }
  .score-num { font-size:44px; font-weight:800; color:${scoreColor}; line-height:1; }
  .conf-badge { display:inline-block; padding:4px 14px; border-radius:99px; font-size:12px; font-weight:600; background:${confBg}; color:${confColor}; }
  .sub { font-size:13px; color:#6b7280; margin-bottom:20px; }
  h2 { font-size:16px; color:#374151; margin:20px 0 10px; padding-bottom:6px; border-bottom:2px solid #e5e7eb; }
  ol { padding:0; list-style:none; }
  hr { border:none; border-top:1px solid #e5e7eb; margin:20px 0 0; }
</style></head>
<body>
<div class="card">
  <h1>Gig Health Score</h1>
  <div class="score-row">
    <div class="score-num">${d.total_score}/100</div>
    <div class="conf-badge">${d.confidence_label}</div>
  </div>
  <div class="sub">Detailed breakdown of each scoring category below.</div>
  <h2>Category Breakdown</h2>
  ${categoryCards}
  <h2>Priority Actions</h2>
  <ol>${priorityItems}</ol>
  <hr>
  <p style="font-size:11px;color:#9ca3af;text-align:center;margin:12px 0 0">Generated by Fiverr Gig Health Analyzer</p>
</div>
</body></html>`;

return [{ json: { html } }];
